Object.assign(SUB_MODEL_FORMULAS, PEDAL_FORMULAS2);
Object.assign(SUB_MODEL_PRE_EQ, AMP_PRE_EQ2);
Object.assign(SUB_MODEL_FORMULAS, AMP_FORMULAS2);
for (const s of SERIES_REGISTRY) {
  for (const m of s.models) {
    const key = seriesModelKey(s, m);
    const formula = SUB_MODEL_FORMULAS[m.key];
    if (formula) SUB_MODEL_FORMULAS[key] = formula;
    const pre = SUB_MODEL_PRE_EQ[m.key];
    if (pre) SUB_MODEL_PRE_EQ[key] = pre;
  }
}
var RATIO_INDEX_TABLE = [1, 1.2, 1.4, 1.6, 1.8, 2, 2.4, 2.8, 3.2, 3.6, 4, 4.4, 4.8, 5.2, 5.6, 6, 6.4, 6.8, 7.2, 7.6, 8, 8.4, 9, 9.6, 10.2, 10.8, 11.4, 12, 13, 14, 15, 16, 17, 18, 19, 20, 22, 24, 26, 30, 100];
function ratioToIndex(target) {
  let best = 0, bestD = Infinity;
  for (let i = 0; i < RATIO_INDEX_TABLE.length; i++) {
    const d = Math.abs(RATIO_INDEX_TABLE[i] - target);
    if (d < bestD) {
      bestD = d;
      best = i;
    }
  }
  return best;
}

// src/data/passThrough.ts
var PASSTHROUGH_PEQ = buildPEQData(PEQ_TYPE.PEAK, freqToIndex(500), 120, 10, 10);
var peqRange = (from, count) => {
  const out = {};
  for (let i = 0; i < count; i++) out[from + i] = PASSTHROUGH_PEQ;
  return out;
};
var PASSTHROUGH_REGS = {
  // 压缩器: 阈值 max + MakeUp min (参数化直通)
  compressor: {
    8: 50,
    13: 0
  },
  // 过载 OD1: 8 段 PEQ 直通 + reg48 主旁路
  overdrive: {
    ...peqRange(44, 4),
    // preEQ 44-47
    ...peqRange(53, 4),
    // postEQ 53-56
    48: 1
    // OD1 主旁路(保留位)
  },
  // 失真 DIST: 8 段 PEQ 直通 + reg63 clip 旁路
  dist: {
    ...peqRange(59, 4),
    // prePEQ 59-62
    ...peqRange(68, 4),
    // postPEQ 68-71
    63: 1
    // DIST clip 旁路(保留位)
  },
  // 箱头: preEQ 4 段 + postEQ 16 段 直通 + reg78 箱头 OD 旁路
  "amp-head": {
    ...peqRange(74, 4),
    // preEQ 74-77
    ...peqRange(83, 16),
    // postEQ 83-98 (16 段)
    78: 1
    // 箱头 OD 旁路(保留位)
  },
  // 箱体: 35 段 PEQ 全平直
  cabinet: peqRange(108, 35),
  // 混响: Mix=0 纯干声
  reverb: {
    229: 0
  },
  // 限幅器: 沿用现成 SPEAKER dynamics「Off」档(不使用已取消的 253)
  limiter: {
    254: 47,
    255: 1,
    256: 150,
    257: 40,
    258: 12,
    259: 0
  }
};
var PASSTHROUGH_MODULES = [
  "compressor",
  "overdrive",
  "dist",
  "amp-head",
  "cabinet",
  "reverb"
];
var LEGACY_BYPASS_MODULES = ["noise-gate", "chorus", "delay"];

// scripts/verify_batch1.ts
var pass = 0;
var fail = 0;
var check = (name, ok, detail = "") => {
  if (ok) {
    pass++;
    console.log(`  OK  ${name}${detail ? "  " + detail : ""}`);
  } else {
    fail++;
    console.log(`  FAIL ${name}  ${detail}`);
  }
};
var hex = (v) => "0x" + (v >>> 0).toString(16).toUpperCase().padStart(8, "0");
console.log("\u2550\u2550\u2550 V1 \u76F4\u901A PEQ \u503C \u2550\u2550\u2550");
check("PASSTHROUGH_PEQ = 0x50A78540", PASSTHROUGH_PEQ === 1353155904, `\u5B9E\u9645 ${hex(PASSTHROUGH_PEQ)}`);
console.log("\n\u2550\u2550\u2550 V2 \u5404\u6A21\u5757\u76F4\u901A\u5BC4\u5B58\u5668\u96C6 \u2550\u2550\u2550");
var P = PASSTHROUGH_PEQ;
var R = PASSTHROUGH_REGS;
check("compressor \u9608\u503C=50", R.compressor?.[8] === 50, `reg8=${R.compressor?.[8]}`);
check("compressor MakeUp=0", R.compressor?.[13] === 0, `reg13=${R.compressor?.[13]}`);
for (const a of [44, 45, 46, 47, 53, 54, 55, 56]) check(`overdrive reg${a} = \u76F4\u901APEQ`, R.overdrive?.[a] === P, hex(R.overdrive?.[a] ?? 0));
check("overdrive reg48 = 1 (\u4E3B\u65C1\u8DEF)", R.overdrive?.[48] === 1);
for (const a of [59, 60, 61, 62, 68, 69, 70, 71]) check(`dist reg${a} = \u76F4\u901APEQ`, R.dist?.[a] === P, hex(R.dist?.[a] ?? 0));
check("dist reg63 = 1 (clip \u65C1\u8DEF)", R.dist?.[63] === 1);
for (const a of [74, 75, 76, 77, ...Array.from({ length: 16 }, (_, i) => 83 + i)])
  check(`amp-head reg${a} = \u76F4\u901APEQ`, R["amp-head"]?.[a] === P, hex(R["amp-head"]?.[a] ?? 0));
check("amp-head reg78 = 1 (\u7BB1\u5934 OD \u65C1\u8DEF)", R["amp-head"]?.[78] === 1);
check(
  "cabinet 35 \u6BB5\u5168 = \u76F4\u901APEQ",
  Array.from({ length: 35 }, (_, i) => 108 + i).every((a) => R.cabinet?.[a] === P),
  `\u6BB5\u6570=${Object.keys(R.cabinet ?? {}).length}`
);
check("reverb reg229 = 0 (Mix \u7EAF\u5E72\u58F0)", R.reverb?.[229] === 0);
check("limiter reg254 = 47 (\u9608\u503C)", R.limiter?.[254] === 47);
check("limiter reg259 = 0 (MakeUp)", R.limiter?.[259] === 0);
check("limiter \u4E0D\u542B\u5DF2\u53D6\u6D88\u7684 253", R.limiter?.[253] === void 0);
console.log("\n\u2550\u2550\u2550 V3 \u76F4\u901A\u96C6\u4E0D\u542B R4 \u53D6\u6D88\u5730\u5740 \u2550\u2550\u2550");
var CANCELLED = [7, 42, 43, 52, 57, 58, 67, 72, 73, 82, 107, 224, 253];
for (const [mid, regs] of Object.entries(R)) {
  const bad = Object.keys(regs).map(Number).filter((a) => CANCELLED.includes(a));
  check(`${mid} \u65E0\u53D6\u6D88\u5730\u5740`, bad.length === 0, bad.length ? `\u8FDD\u89C4: ${bad.join(",")}` : "");
}
console.log("\n\u2550\u2550\u2550 V4 \u8E29\u9489\u5206\u7C7B \u2550\u2550\u2550");
check(
  "\u4FDD\u7559\u65C1\u8DEF = noise-gate/chorus/delay",
  [...LEGACY_BYPASS_MODULES].sort().join(",") === ["noise-gate", "chorus", "delay"].sort().join(","),
  [...LEGACY_BYPASS_MODULES].join(",")
);
check(
  "\u590D\u4F4D\u76F4\u901A = compressor/overdrive/dist/amp-head/cabinet/reverb",
  [...PASSTHROUGH_MODULES].sort().join(",") === ["compressor", "overdrive", "dist", "amp-head", "cabinet", "reverb"].sort().join(","),
  [...PASSTHROUGH_MODULES].join(",")
);
check("\u4E24\u7C7B\u4E92\u4E0D\u91CD\u53E0", PASSTHROUGH_MODULES.every((m) => !LEGACY_BYPASS_MODULES.includes(m)));
console.log(`
\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 \u603B\u7ED3: ${pass} PASS / ${fail} FAIL ${fail === 0 ? "\u2192 \u9A8C\u8BC1\u901A\u8FC7" : "\u2192 \u9700\u4FEE\u6B63"}`);
process.exit(fail === 0 ? 0 : 1);
